  "properties": {
    "message": {
      "type": "string",
      "description": "Next message for chat"
    },
    "number_of_questions": {
      "type": "integer",
      "description": "Number of questions"
    },
    "topic": {
      "type": "string",
      "description": "Topic"
    },
    "tested_users_bbcodes": {
      "type": "array",
      "items": {
        "type": "string",
        "description": "Tested User in bbcode format [USER=id][USER=id]name[/USER][/USER]"
      }
    },
    "questions_is_approved": {
      "type": "boolean",
      "description": "questions is approved"
    },
    "input_data_is_known": {
      "type": "boolean",
      "description": "Input data is known"
    },
    "questions": {
      "type": "string",
      "description": "Questions of test"
    }
  },
  "required": [
    "message",
    "number_of_questions",
    "topic",
    "tested_user_ids",
    "questions_is_approved",
    "input_data_is_known",
    "questions"
  ]
}

